import math


def _vy(v0: float, theta_deg: float, g: float) -> float:
    return v0 * math.sin(math.radians(theta_deg))


def time_of_flight(v0: float, theta_deg: float, g: float) -> float:
    """Total flight time: t = 2*v0*sin(theta)/g."""
    return 2.0 * _vy(v0, theta_deg, g) / g


def max_height(v0: float, theta_deg: float, g: float) -> float:
    """Apex height: h = (v0*sin(theta))^2 / (2*g)."""
    return _vy(v0, theta_deg, g) ** 2 / (2.0 * g)


def range_(v0: float, theta_deg: float, g: float) -> float:
    """Horizontal range: R = v0^2 * sin(2*theta) / g."""
    return v0**2 * math.sin(2.0 * math.radians(theta_deg)) / g
