    within(range_(V0, THETA, G), 40.775)


def test_max_height():
    within(max_height(V0, THETA, G), 10.194)


def test_time_of_flight():
    within(time_of_flight(V0, THETA, G), 2.883)


def test_complementary_angles():
    assert math.isclose(
        range_(V0, 30.0, G), range_(V0, 60.0, G), abs_tol=1e-9
    )
